Q: How to bind an entire control instead of individual properties in WPF A: <p>There have been many answers here outlining how to approach this, but I wanted to give you an option without using code behind.<br />
So let's start with your Model, TestClass:</p>
<pre><code>public class TestClass: INotifyPropertyChanged
{
    public event PropertyChangedEventHandler PropertyChanged;

    protected void OnPropertyChanged(string propertyName)
    {
        PropertyChanged?.Invoke(this, new PropertyChangedEventArgs(propertyName));
    }

    private string _DebugMsg;
    public string DebugMsg
    {
            get { return _DebugMsg; }
            set { _DebugMsg = value; OnPropertyChanged(&quot;DebugMsg&quot;); }
    }

    public void DebugMsgButton()
    {
        this.DebugMsg += &quot;\ntest class&quot;;
    }  
    private EStatus status;

    public EStatus Status
    {
        get { return status; }
        set { status = value; OnPropertyChanged(nameof(Status)); }
    }
}  
//your class needs a status to determine colour of your text block  
public enum EStatus
{
    Good,
    Bad,
    Ugly//this is a movie reference
}
</code></pre>
<p>Now that you have a ability to determine and save state of a model, you can determine which colour to use depending on status.</p>
<pre><code>    &lt;Grid Background=&quot;{DynamicResource {x:Static SystemColors.ControlLightBrushKey}}&quot;&gt;
        &lt;Grid.RowDefinitions&gt;
            &lt;RowDefinition Height=&quot;50&quot; /&gt;
            &lt;RowDefinition Height=&quot;Auto&quot; /&gt;
            &lt;RowDefinition Height=&quot;Auto&quot; /&gt;
            &lt;RowDefinition /&gt;
        &lt;/Grid.RowDefinitions&gt;
        &lt;Grid.ColumnDefinitions&gt;
            &lt;ColumnDefinition /&gt;
            &lt;ColumnDefinition /&gt;
        &lt;/Grid.ColumnDefinitions&gt;
        &lt;DockPanel Grid.Column=&quot;1&quot; LastChildFill=&quot;True&quot;&gt;
            &lt;Border BorderBrush=&quot;Black&quot; BorderThickness=&quot;1&quot;&gt;
                &lt;TextBlock Background=&quot;{Binding TestClass.Status, Converter={StaticResource StatusToBackgroundConverter}}&quot; Text=&quot;{Binding TestClass.DebugMsg}&quot; /&gt;
            &lt;/Border&gt;
        &lt;/DockPanel&gt;
        &lt;Button
            Grid.Row=&quot;1&quot;
            Width=&quot;226&quot;
            Height=&quot;33&quot;
            Command=&quot;{Binding DebugMessageCommand}&quot;
            Content=&quot;Debug Message&quot; /&gt;
        &lt;Button
            Grid.Row=&quot;2&quot;
            Width=&quot;226&quot;
            Height=&quot;35&quot;
            Command=&quot;{Binding BackgroundColourCommand}&quot;
            Content=&quot;Background color&quot; /&gt;
    &lt;/Grid&gt;
</code></pre>
<p>Then in your View Model you would have something like this:</p>
<pre><code>    public class MainViewModel : BaseViewModel
    {
        public MainViewModel()
        {
            Title = &quot;Main View Model&quot;;

            TestClass = new TestClass();
            DebugMessageCommand = new RelayCommand(DebugMessage);
            BackgroundColourCommand = new RelayCommand(BackgroundColour);
        }


        private void DebugMessage()
        {
            TestClass.DebugMsg = &quot;Debug Message TC&quot;;
        }

        private IRelayCommand debugMessageCommand;

        public IRelayCommand DebugMessageCommand
        {
            get { return debugMessageCommand; }
            set { debugMessageCommand = value; OnPropertyChanged(); }
        }
        private void BackgroundColour()
        {
            TestClass.Status = EStatus.Ugly;
        }

        private IRelayCommand backgroundColourCommand;

        public IRelayCommand BackgroundColourCommand
        {
            get { return backgroundColourCommand; }
            set { backgroundColourCommand = value; OnPropertyChanged(); }
        }


        private TestClass testClass;

        public TestClass TestClass
        {
            get { return testClass; }
            set { testClass = value; OnPropertyChanged(); }
        }
    }
</code></pre>
<p>To use VM in your window you need to declare namespace like this:<br />
<code>xmlns:vm=&quot;clr-namespace:SO_WPF.ViewModels&quot;</code> your namespace will differ.<br />
And a converter: <code>xmlns:converters=&quot;clr-namespace:SO_WPF.Converters&quot;</code>
Now in Main Window, declare:</p>
<pre><code>    &lt;Window.DataContext&gt;
        &lt;vm:MainViewModel /&gt;
    &lt;/Window.DataContext&gt;
    &lt;Window.Resources&gt;
        &lt;converters:StatusToBackgroundConverter x:Key=&quot;StatusToBackgroundConverter&quot; /&gt;
    &lt;/Window.Resources&gt;
</code></pre>
<p>Now that you have your model, your view model too, we need a converter so we can use it in our UI. As luck would have it, I have one, here it is:</p>
<pre><code>    public class StatusToBackgroundConverter : IValueConverter
    {
        public Brush GoodBrush { get; set; } = Brushes.ForestGreen;
        public Brush BadBrush { get; set; } = Brushes.IndianRed;
        public Brush UglyBrush { get; set; } = Brushes.Khaki;
        public object Convert(object value, Type targetType, object parameter, CultureInfo culture)
        {
            var result = (Brush)null;
            if (value is EStatus status)
            {
                switch (status)
                {
                    case EStatus.Good:
                        result = GoodBrush;
                        break;
                    case EStatus.Bad:
                        result = BadBrush;
                        break;
                    case EStatus.Ugly:
                        result = UglyBrush;
                        break;
                    default:
                        result = Brushes.HotPink;
                        break;
                }
            }

            return result;
        }

        public object ConvertBack(object value, Type targetType, object parameter, CultureInfo culture)
        {
            throw new NotImplementedException();
        }
    }
</code></pre>
<p>So your View model now holds all of the necessary information for your view, like view model should and there are no UI elements held in it either. Just in case you don't have RelayCommand here is a simple implementation you can use:</p>
<pre><code>    public class RelayCommand : IRelayCommand
    {
        private Action _execute;
        private Func&lt;bool&gt; _canExecute;
        private readonly ICommand Command;

        public event EventHandler? CanExecuteChanged;

        public RelayCommand(Action execute, Func&lt;bool&gt; canExecute)
        {
            _execute = execute ?? throw new ArgumentNullException(nameof(execute));
            _canExecute = canExecute ?? throw new ArgumentNullException(nameof(canExecute));
        }

        public RelayCommand(Action execute)
        {
            _execute = execute ?? throw new ArgumentNullException(nameof(execute));
            _canExecute = () =&gt; true;
        }

        private RelayCommand()
        {
            Command = (ICommand)this;
        }

        bool ICommand.CanExecute(object? parameter)
        {
            return _canExecute();
        }

        void ICommand.Execute(object? parameter)
        {
            _execute();
        }

        public void Refresh()
        {
            CanExecuteChanged?.Invoke(this, EventArgs.Empty);
        }

        public void Execute()
        {
            Command.Execute(null);
        }

        public bool CanExecute()
        {
            return Command.CanExecute(null);
        }
    }
</code></pre>
<p>Have a go at it, and try to write tests for code behind solution and test for this approach and see which one is easier to test.</p>

Q: using argon2 from zig standard library (v0.16.0) verifyHash crashes with a padding error when writing to and reading from a file A: <p>I had overlooked the solution, because I thought I had already tested for it.</p>
<p>I needed to construct a slice of length of the file to contain the contents of the file that was read in the verify function rather than coercing the entire buffer. This can be accomplished by using the slice length returned from readSliceShort():</p>
<pre class="lang-rust prettyprint-override"><code>// Read the hash in from the file
var hashbuf: [PSKLEN]u8 = undefined;
const hash_len = try hash_in.readSliceShort(&amp;hashbuf);
var hash: []u8 = &amp;hashbuf;
hash.len = hash_len;
</code></pre>
<p>So, the argon2 algorithm was not able to run its verify function because I was passing an entire buffer that didn't have the proper padding (and incidentally contained garbage unintialized data).</p>

Q: ModalPopup not working in the Content Page of the Master Page A: <p>Generally you should put the ScriptManager in your Master page.  Then place a ScriptManagerProxy or ToolkitManagerProxy in your aspx page.  Also if you are working with .Net 4.0 then you might want to specify AjaxFrameworkMode="Enabled"</p>

<p>You shouldn't need an UpdatePanel for this hello world test.</p>

<p><strong>MasterPage.master</strong></p>

<pre><code>&lt;%@ Master Language="C#" AutoEventWireup="true" CodeFile="MasterPage.master.cs" Inherits="MasterPage" %&gt;

&lt;!DOCTYPE html PUBLIC "-//W3C//DTD XHTML 1.0 Transitional//EN" "http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd"&gt;
&lt;html xmlns="http://www.w3.org/1999/xhtml"&gt;
&lt;head id="Head1" runat="server"&gt;
    &lt;title&gt;&lt;/title&gt;
    &lt;asp:ContentPlaceHolder ID="head" runat="server"&gt;
    &lt;/asp:ContentPlaceHolder&gt;
&lt;/head&gt;
&lt;body&gt;
    &lt;form id="form1" runat="server"&gt;
    &lt;asp:ScriptManager ID="ScriptManager1" AjaxFrameworkMode="Enabled" runat="server"&gt;&lt;/asp:ScriptManager&gt;
    &lt;asp:ContentPlaceHolder ID="ContentPlaceHolder1" runat="server"&gt;
    &lt;/asp:ContentPlaceHolder&gt;
    &lt;/form&gt;
&lt;/body&gt;
&lt;/html&gt;
</code></pre>

<p><strong>Default.aspx</strong></p>

<pre><code>&lt;%@ Page Title="" Language="C#" MasterPageFile="~/MasterPage.master" AutoEventWireup="true" CodeFile="Default.aspx.cs" Inherits="_Default" %&gt;

&lt;%@ Register Assembly="AjaxControlToolkit" Namespace="AjaxControlToolkit" TagPrefix="cc1" %&gt;

&lt;asp:content id="Content1" contentplaceholderid="head" runat="Server"&gt;
    &lt;link type="text/css" rel="Stylesheet" href="StyleSheet.css" /&gt;
&lt;/asp:content&gt;
&lt;asp:content id="Content2" contentplaceholderid="ContentPlaceHolder1" runat="Server"&gt;
    &lt;asp:ScriptManagerProxy ID="ScriptManagerProxy1"runat="server"&gt;&lt;/asp:ScriptManagerProxy&gt;

    &lt;asp:Panel ID="pnl1" runat="server" Height="200" Width="200" CssClass="modalPopup"&gt;
        &lt;h1&gt;
            Hello World
        &lt;/h1&gt;
        &lt;asp:Button runat="server" Text="ButtonOk"&gt;&lt;/asp:Button&gt;
        &lt;asp:Button runat="server" Text="ButtonCancel"&gt;&lt;/asp:Button&gt;
    &lt;/asp:Panel&gt;

    &lt;asp:Button ID="btnShow" runat="server" Text="Show" /&gt;

    &lt;cc1:ModalPopupExtender ID="mpEditComment" 
        PopupControlID="pnl1" 
        TargetControlID="btnShow"
        OkControlID="ButtonOk"
        CancelControlID="ButtonCancel"
        BackgroundCssClass="modalBackground"
        runat="server"  /&gt;

&lt;/asp:content&gt;
</code></pre>
